/* ---- Lookup ---- */

static int cmp(const char *s, uint32_t len, const char *nm)
{
    uint32_t k = 0;
    while (k < len && nm[k]) {
        int d = toupper((unsigned char)s[k]) - (unsigned char)nm[k];
        if (d) return d;
        k++;
    }
    if (k == len && nm[k] == '\0') return 0;
    return nm[k] ? -1 : 1;
}

const gp_ent_t *gp_find(const char *s, uint32_t len)
{
    if (!s || len == 0 || len > TAL_MAX_IDENT) return NULL;
    uint32_t lo = 0, hi = gp_n;
    for (uint32_t it = 0; it < 32 && lo < hi; it++) {
        uint32_t mid = lo + (hi - lo) / 2;
        int d = cmp(s, len, gp_tab[mid].name);
        if (d == 0) return &gp_tab[mid];
        if (d < 0) hi = mid; else lo = mid + 1;
    }
    return NULL;
}

const sf_ent_t *sf_find(const char *s, uint32_t len)
{
    if (!s || len == 0 || len > TAL_MAX_IDENT) return NULL;
    for (uint32_t i = 0; i < sf_n; i++)
        if (cmp(s, len, sf_tab[i].name) == 0) return &sf_tab[i];
    return NULL;
}
